<?php $this->layout('layout', ['meta_title' => 'Edit Resource | SwimSnap']) ?>
<nav aria-label="breadcrumb"><ol class="breadcrumb mb-4"><li class="breadcrumb-item"><a href="<?= $base_url ?>/">Home</a></li><li class="breadcrumb-item"><a href="<?= $base_url ?>/resources/">Resources</a></li><li class="breadcrumb-item active">Edit</li></ol></nav>
<h1 class="mb-1">Edit resource</h1><p class="text-muted mb-4">Correct the title, description, or category shown for this shared website.</p>
<form method="post" action="<?= $base_url ?>/resources/update.php" class="card shadow-sm"><div class="card-body"><input type="hidden" name="url" value="<?= htmlspecialchars($resource['url']) ?>"><div class="mb-3"><label class="form-label" for="title">Title</label><input class="form-control" id="title" name="title" maxlength="180" required value="<?= htmlspecialchars($resource['title'] ?? '') ?>"></div><div class="mb-3"><label class="form-label" for="description">Description</label><textarea class="form-control" id="description" name="description" maxlength="500" rows="5"><?= htmlspecialchars($resource['description'] ?? '') ?></textarea></div><div class="mb-3"><label class="form-label" for="category">Category</label><select class="form-select" id="category" name="category"><?php foreach (['national' => 'National', 'zone' => 'Zone', 'lsc' => 'LSC'] as $value => $label): ?><option value="<?= $value ?>" <?= ($resource['category'] ?? '') === $value ? 'selected' : '' ?>><?= $label ?></option><?php endforeach; ?></select></div><div class="d-flex gap-2"><a class="btn btn-outline-secondary" href="<?= $base_url ?>/resources/">Cancel</a><button class="btn btn-primary" type="submit">Save changes</button></div></div></form>
<script>
(() => { const category=document.querySelector('#category'), regions=<?= json_encode($regions) ?>, currentZone=<?= json_encode($resource['zone_code'] ?? '') ?>, currentLsc=<?= json_encode($resource['lsc_code'] ?? '') ?>; const zone=document.createElement('select'), lsc=document.createElement('select'); zone.name='zone_code'; lsc.name='lsc_code'; zone.className=lsc.className='form-select'; zone.innerHTML='<option value="">Select zone</option>'+Object.entries(regions).map(([code,item])=>`<option value="${code}">${item[0]}</option>`).join(''); zone.value=currentZone; const zoneGroup=document.createElement('div'), lscGroup=document.createElement('div'); zoneGroup.className=lscGroup.className='mb-3'; zoneGroup.innerHTML='<label class="form-label">Zone</label>'; lscGroup.innerHTML='<label class="form-label">LSC</label>'; zoneGroup.append(zone); lscGroup.append(lsc); category.parentElement.after(zoneGroup,lscGroup); function refresh(){ const items=regions[zone.value]?.[1]||{}; lsc.innerHTML='<option value="">Select LSC</option>'+Object.entries(items).map(([code,name])=>`<option value="${code}">${name}</option>`).join(''); if(zone.value===currentZone) lsc.value=currentLsc; const national=category.value==='national', isLsc=category.value==='lsc'; zoneGroup.classList.toggle('d-none',national); lscGroup.classList.toggle('d-none',!isLsc); zone.required=!national; lsc.required=isLsc; } category.addEventListener('change',refresh); zone.addEventListener('change',()=>{ lsc.value=''; refresh(); }); refresh(); })();
</script>
